  //   => [2, 1, 1, 3, 2, 1, 3, 1, 23]
  it.todo("test_continued_fraction:46");
  it("test_continued_fraction:54", () => {
    const v1 = continuedFractionIterator(rational(17, 12));
    expect(sympyStr(pyItems([v1.next().value, v1.next().value, v1.next().value, v1.next().value]))).toBe('[1, 2, 2, 2]');
  });
  it("test_continued_fraction:55", () => {
    const v1 = continuedFractionIterator(rational(-17, 12));
    expect(sympyStr(pyItems([v1.next().value, v1.next().value, v1.next().value, v1.next().value, v1.next().value]))).toBe('[-2, 1, 1, 2, 2]');
  });
  it("test_continued_fraction:57", () => {
    const v1 = continuedFractionConvergents([1, 6, 1, 8]);
    expect(sympyStr(pyItems([v1.next().value, v1.next().value, v1.next().value, v1.next().value]))).toBe('[1, 7/6, 8/7, 71/62]');
  });
  it("test_continued_fraction:58", () => {
    expect(sympyStr(pyItems([continuedFractionConvergents([2]).next().value]))).toBe('[2]');
  });
  it("test_continued_fraction:59", () => {
    const v1 = continuedFractionConvergents([1, 1, 1, 1, 1, 1, 1]);
    expect(sympyStr(pyItems([v1.next().value, v1.next().value, v1.next().value, v1.next().value, v1.next().value, v1.next().value, v1.next().value]))).toBe('[1, 2, 3/2, 5/3, 8/5, 13/8, 21/13]');
  });
  it("test_continued_fraction:61", () => {
    const v1 = continuedFractionConvergents([1, 6, rational(-1, 2), 4]);
    expect(sympyStr(pyItems([v1.next().value, v1.next().value, v1.next().value, v1.next().value]))).toBe('[1, 7/6, 5/4, 3/2]');
  });
  it("test_continued_fraction:71", () => {
    expect(sympyStr(continuedFractionReduce([1, 6, 1, 8]))).toBe('71/62');
  });
  it("test_continued_fraction:72", () => {
    expect(sympyStr(continuedFractionReduce([3]))).toBe('3');
  });
  it("test_continued_fraction:73", () => {
    expect(sympyStr(continuedFractionReduce([-1, 5, 1, 4]))).toBe('-24/29');
  });
  it("test_continued_fraction:74", () => {
    expect(sympyStr(expand(new Add([rational(-2, 7), new Mul([rational(-1, 7), new Pow(rational(3), rational(1, 2))]), new Mul([rational(1, 7), new Add([rational(2), new Pow(rational(3), rational(1, 2))])])]), {}))).toBe('0');
  });
  it("test_continued_fraction:75", () => {
    expect(sympyStr(continuedFractionReduce([1, 5, 9]))).toBe('55/46');
  });
  it("test_continued_fraction:76", () => {
    expect(sympyStr(expand(new Add([rational(-1, 2), new Mul([rational(1, 2), new Add([rational(1), new Pow(rational(5), rational(1, 2))])]), new Mul([rational(-1, 2), new Pow(rational(5), rational(1, 2))])]), {}))).toBe('0');
  });
  it("test_continued_fraction:77", () => {
    expect(sympyStr(continuedFractionReduce([-3, 1, 1, [2]]))).toBe('-sqrt(2) - 1');
  });
